-- Full-text values use statement memory beyond the former 512-item and
-- 2,048-total-position implementation envelopes while preserving PostgreSQL's
-- 256-position boundary for each lexeme. The wide query stays an expression:
-- PostgreSQL's PLAIN tsquery storage can make a 599-node value exceed one heap
-- tuple even though the value is valid at SQL and wire boundaries.
CREATE TABLE wide_full_text_values (
  id integer PRIMARY KEY,
  terms tsvector NOT NULL
);

